import json,numpy as np
from PIL import Image,ImageDraw
p='/app/output/obs015';c='robot0_eye_in_hand';m=json.load(open(p+'/meta.json'));d=np.load(p+'/depth_'+c+'.npy')[-1];im=np.array(Image.open(p+'/last/'+c+'.jpg'));K=np.array(m['cameras'][c]['intrinsic_cv']);T=np.array(m['cameras'][c]['cam2world_gl']);out=Image.fromarray(im).resize((960,720));dr=ImageDraw.Draw(out)
for v in range(160,210,5):
 for u in range(90,260,10):
  if im[v,u,2]>im[v,u,0]+15 and im[v,u,2]>im[v,u,1]+10:
   z=float(d[v,u]);q=np.linalg.inv(K)@np.array([u,v,1])*z;w=T@np.r_[q[0],-q[1],-q[2],1];print(u,v,z,np.round(w[:3],4))
for u in range(80,280,20):dr.line((u*3,0,u*3,720),fill='gray');dr.text((u*3+2,630),str(u),fill='yellow')
for v in range(100,220,20):dr.line((0,v*3,960,v*3),fill='gray');dr.text((20,v*3),str(v),fill='yellow')
out.save('/app/output/grid.jpg')
PY","max_output_tokens":3000}));
